mapper.select:
SELECT id, family_id, expires_at, reason, status, attempts, next_retry_at,
       completed_at, created_at, updated_at
FROM auth_cleanup_tasks
WHERE status = 'PENDING' AND next_retry_at <= #{now}
ORDER BY next_retry_at, id
LIMIT #{limit}

mapper.update:
UPDATE auth_cleanup_tasks
SET status = 'COMPLETED', completed_at = #{now}, updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING'

UPDATE auth_cleanup_tasks
SET attempts = attempts + 1, next_retry_at = #{nextRetryAt}, updated_at = #{now}
WHERE id = #{id} AND status = 'PENDING' AND attempts = #{attempts}
